Here's a Python program that meets your requirements. This program uses a dictionary to store the contacts and allows users to add, remove, and search for contacts.

```python
# Initialize an empty phonebook dictionary
phonebook = {}

def add_contact(name, number):
    """Add a contact to the phonebook."""
    if name in phonebook:
        print(f"Contact {name} already exists. Phone number updated.")
    else:
        phonebook[name] = number
        print(f"Contact {name} added successfully.")

def remove_contact(name):
    """Remove a contact from the phonebook."""
    if name in phonebook:
        del phonebook[name]
        print(f"Contact {name} removed successfully.")
    else:
        print(f"Contact {name} not found.")

def search_contact(name):
    """Search for a contact in the phonebook."""
    if name in phonebook:
        print(f"{name}: {phonebook[name]}")
    else:
        print(f"Contact {name} not found.")

# Function to run the program
def run_program():
    while True:
        command = input("Enter a command (add, remove, search, or exit): ").lower()

        if command == "add":
            name = input("Enter the name: ")
            number = input("Enter the phone number: ")
            add_contact(name, number)

        elif command == "remove":
            name = input("Enter the name: ")
            remove_contact(name)

        elif command == "search":
            name = input("Enter the name: ")
            search_contact(name)

        elif command == "exit":
            print("Exiting the program...")
            break

        else:
            print("Invalid command. Please try again.")

# Run the program
run_program()
```

This program will allow users to add, remove, and search for contacts in the phonebook. The sample input and output are provided to demonstrate the functionality.
